"use client"

import * as React from "react"
import { CircleAlertIcon, CircleHelpIcon, InfoIcon as LucideInfo } from "lucide-react"
import { cn } from "cn"

function InfoIcon({
  className,
  label,
  body,
  tone = "info",
}: {
  className?: string
  label: string
  body: string
  tone?: "info" | "help" | "alert"
}) {
  const [open, setOpen] = React.useState(false)

  function Glyph() {
    if (tone === "help") {
      return <CircleHelpIcon className="size-4" />
    }
    if (tone === "alert") {
      return <CircleAlertIcon className="size-4" />
    }
    return <LucideInfo className="size-4" />
  }

  return (
    <span data-slot="info-icon" className={cn("relative inline-flex", className)}>
      <button
        type="button"
        aria-label={label}
        aria-expanded={open}
        className="rounded-full p-1 text-muted-foreground hover:bg-muted hover:text-foreground"
        onClick={() => setOpen(!open)}
      >
        <Glyph />
      </button>
      {open ? (
        <span className="absolute top-7 left-0 z-20 w-56 rounded-lg border border-border bg-background p-2 text-xs text-muted-foreground shadow-md">
          {body}
        </span>
      ) : null}
    </span>
  )
}

function QuestionIcon({
  className,
  label,
  body,
}: {
  className?: string
  label: string
  body: string
}) {
  return (
    <InfoIcon
      className={className}
      label={label}
      body={body}
      tone="help"
    />
  )
}

export { InfoIcon, QuestionIcon }
